const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(value||0);
const date=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const stageLabels={chat:'Project chat',jurisdiction:'Jurisdiction',contacts:'Contacts & process',codes:'Codes & standards',verification:'Opus evidence check',review:'Final report'};
const disciplines=['Architecture','Fire protection','Electrical','Mechanical','Plumbing','Structural','Civil'];
const statuses={queued:'Queued',researching:'Researching',waiting_batch:'Batch queued',needs_key:'Needs API key',budget:'Budget reached',attention:'Needs attention',canceled:'Canceled',canceling:'Canceling',partial:'Needs confirmation',complete:'Research complete',failed:'Interrupted',waiting:'Waiting to retry'};
let state={bootstrap:null,projects:[],selected:null,detail:null,tab:'overview',action:null,formBusy:false}, timer;
let diagnosticsSnapshot=null,diagnosticsLoad=0,clientErrorCount=0,clientErrorWindow=Date.now();
const questionDrafts=new Map(),questionBusy=new Set();
const chatDrafts=new Map(),chatOptions=new Map(),chatPending=new Set(),chatErrors=new Map(),chatRequests=new Map(),chatOlder=new Map();
let projectLoad=0;
function recordClientError(message,location='',line=0){
  if(!state.bootstrap)return;if(Date.now()-clientErrorWindow>60000){clientErrorCount=0;clientErrorWindow=Date.now();}if(++clientErrorCount>10)return;
  fetch('/api/diagnostics/client',{method:'POST',headers:{'Content-Type':'application/json','X-App-Token':state.bootstrap.token},body:JSON.stringify({message:String(message||'Browser error').slice(0,2000),location:String(location).slice(0,300),line,projectId:state.selected})}).catch(()=>{});
}
window.addEventListener('error',e=>recordClientError(e.message,e.filename,e.lineno));
window.addEventListener('unhandledrejection',e=>recordClientError(e.reason?.message||'An asynchronous browser operation failed.'));
async function api(url,options={}){
  let response;try{response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(state.bootstrap?{'X-App-Token':state.bootstrap.token}:{}),...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});}catch(e){recordClientError('The browser could not reach the local application.',url);throw e;}
  const data=await response.json();if(!response.ok)throw new Error(data.error||'The request could not be completed.');return data;
}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,5000);}
async function loadDiagnostics(){
  const load=++diagnosticsLoad;diagnosticsSnapshot=null;$('#download-diagnostics').disabled=true;$('#diagnostic-content').innerHTML='<p class="muted" style="margin-top:20px">Loading saved records…</p>';
  try{
    const report=await api('/api/diagnostics',{method:'POST',body:{projectId:$('#diagnostic-project').value||null}});if(load!==diagnosticsLoad)return;diagnosticsSnapshot=report;
    const attempts=report.projects.flatMap(p=>p.attempts.map(a=>({...a,projectId:p.id}))).sort((a,b)=>b.created.localeCompare(a.created));
    const failed=attempts.filter(a=>['errored','unknown'].includes(a.state)),events=report.events.slice(0,80);
    $('#diagnostic-content').innerHTML=`<div class="diagnostic-summary"><div><small>APP VERSION</small><strong>${esc(report.application.version)}</strong></div><div><small>REQUESTS RECORDED</small><strong>${attempts.length}</strong></div><div><small>FAILED / UNCERTAIN</small><strong>${failed.length}</strong></div></div><p class="field-help">Snapshot ${esc(date(report.generatedAt))}. Errors below may be historical and already resolved.</p>${report.projects.filter(p=>['attention','budget','needs_key','failed'].includes(p.status)).map(p=>`<div class="notice"><strong>${esc(statuses[p.status]||p.status)}</strong><p>${esc(p.note||'Review the request history for this project.')}</p></div>`).join('')}<details class="diagnostic-section" open><summary>Progress and recovery</summary>${report.projects.map(p=>`<div class="diagnostic-project"><p class="field-help">Project ${esc(p.id.slice(0,8))} · ${esc(statuses[p.status]||p.status)} · ${esc(money(p.cost))} recorded · ${p.sourceCount} sources</p><div class="diagnostic-stages">${p.stages.map(s=>`<div><strong>${esc(stageLabels[s.id]||s.id)}</strong><span>${esc(s.status)} · ${s.rounds} requests</span></div>`).join('')}</div></div>`).join('')||'<p>No projects yet.</p>'}</details><details class="diagnostic-section"><summary>Request history (${attempts.length})</summary><p class="field-help">Showing the latest 30. The download includes every saved request summary.</p>${attempts.slice(0,30).map(a=>`<details class="diagnostic-entry"><summary>${esc(stageLabels[a.stage]||a.stage)} · ${esc(a.state)} · ${esc(date(a.created))}</summary><pre>${esc(JSON.stringify(a,null,2))}</pre></details>`).join('')||'<p>No requests recorded.</p>'}</details><details class="diagnostic-section" open><summary>Detailed events (${report.events.length})</summary><p class="field-help">Showing the latest 80. Up to ${report.retention.maximumEvents.toLocaleString()} events are retained locally across the workspace.</p>${events.map(e=>`<details class="diagnostic-entry"><summary><span class="status-pill ${e.level==='error'?'red':e.level==='warning'?'amber':''}">${esc(e.level)}</span> ${esc(e.event)} <span class="field-help">${esc(date(e.time))}</span></summary><pre>${esc(JSON.stringify({time:e.time,projectId:e.project_id,stage:e.stage_id,attemptId:e.attempt_id,...e.details},null,2))}</pre></details>`).join('')||'<p>Detailed tracing begins with this update. Historical request summaries remain available above.</p>'}</details><p class="field-help">${esc(report.retention.note)}</p>`;
    $('#download-diagnostics').disabled=false;
  }catch(e){if(load===diagnosticsLoad)$('#diagnostic-content').innerHTML=`<div class="inline-error" role="alert">${esc(e.message)}</div>`;}
}
$('#open-diagnostics').addEventListener('click',()=>{ $('#settings-dialog').close();$('#diagnostic-project').innerHTML='<option value="">Entire workspace</option>'+state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===state.selected?'selected':''}>${esc(p.name)}</option>`).join('');$('#diagnostics-dialog').showModal();loadDiagnostics();});
$('#diagnostic-project').addEventListener('change',loadDiagnostics);
$('#refresh-diagnostics').addEventListener('click',loadDiagnostics);
$('#download-diagnostics').addEventListener('click',()=>{if(!diagnosticsSnapshot)return;const a=document.createElement('a');a.href='/api/diagnostics/download'+($('#diagnostic-project').value?'?project='+encodeURIComponent($('#diagnostic-project').value):'');a.download='AHJ-Atlas-diagnostics.json';document.body.appendChild(a);a.click();a.remove();});
const icons={pin:'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/></svg>',people:'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v2"/></svg>',book:'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 4h14a2 2 0 0 1 2 2v15H6a2 2 0 0 1-2-2V4Zm0 13h16M8 8h8M8 11h6"/></svg>',check:'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg>'};
function newForm(prefill={}){
  projectLoad++;
  const custom=Boolean(prefill.discipline&&!disciplines.includes(prefill.discipline));
  state.selected=null;state.detail=null;state.tab='overview';history.replaceState(null,'','/');renderSidebar();$('#breadcrumb').innerHTML='WORKSPACE <span>/</span> NEW RESEARCH';
  $('#main').innerHTML=`<div class="intro"><div><span class="eyebrow">A BETTER START TO DESIGN</span><h1>Know your jurisdiction.</h1><p>Find the authorities, people, and adopted codes that matter to your project.</p></div><span class="intro-badge">Built for engineers & architects</span></div>
  <div class="new-grid"><form id="project-form" class="panel"><div class="panel-padding"><div class="panel-head"><span class="step-number">01</span><h2>Your project</h2></div>
  <div class="field"><label for="address">Project address</label><input id="address" name="address" required minlength="8" maxlength="500" autocomplete="street-address" placeholder="Street address, city, state, ZIP" value="${esc(prefill.address||'')}"><p class="field-help">A complete address helps distinguish city, county, and special-district authority.</p></div>
  <div class="form-row"><div class="field"><label for="discipline">Your discipline</label><select name="discipline" id="discipline" required><option value="">Select your discipline</option>${disciplines.map(d=>`<option ${prefill.discipline===d?'selected':''}>${d}</option>`).join('')}<option value="Other" ${custom?'selected':''}>Other — enter your discipline</option></select><div class="field" id="custom-discipline-field" ${custom?'':'hidden'} style="margin-top:14px"><label for="custom-discipline">Your discipline or specialty</label><input id="custom-discipline" name="customDiscipline" minlength="2" maxlength="100" placeholder="e.g. Acoustics, telecommunications" value="${esc(custom?prefill.discipline:'')}" ${custom?'required':'disabled'}><p class="field-help">Research will follow the discipline you enter.</p></div></div><div class="field"><label for="name">Project name</label><input id="name" name="name" required maxlength="100" placeholder="e.g. Westside renovation" value="${esc(prefill.name||'')}"></div></div>
  <details class="extra" ${prefill.notes?'open':''}><summary>Add project context <span class="optional">optional</span></summary><div class="form-row"><div class="field"><label for="scope">Scope of work <span class="optional">optional</span></label><select name="scope" id="scope">${['Not yet specified','New construction','Renovation / alteration','Addition','Tenant improvement','Change of occupancy','Existing building assessment'].map(s=>`<option ${prefill.scope===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="occupancy">Building use <span class="optional">optional</span></label><input id="occupancy" name="occupancy" placeholder="e.g. Warehouse, office" value="${esc(prefill.occupancy||'')}"></div></div><div class="form-row"><div class="field"><label for="permit-date">Expected permit date <span class="optional">optional</span></label><input type="date" name="permitDate" id="permit-date" value="${esc(prefill.permitDate||'')}"></div><div class="field"><label for="country">Country <span class="optional">optional</span></label><input id="country" name="country" value="${esc(prefill.country||'United States')}"></div></div><label for="notes">Additional context <span class="optional">optional</span></label><textarea id="notes" name="notes" rows="3" maxlength="4000" placeholder="Known AHJ, proposed systems (sprinklers, pumps, batteries, generators, fuel), equipment quantities, and owner/insurer requirements">${esc(prefill.notes||'')}</textarea></details>
  <div class="section-divider"></div><div class="panel-head"><span class="step-number">02</span><h2>How would you like to research?</h2></div><div class="mode-choices"><label class="mode-choice"><span class="mode-title"><input type="radio" name="mode" value="realtime" ${prefill.mode!=='batch'?'checked':''}> Research now</span><p>Start immediately.<br>Follow progress as it happens.</p></label><label class="mode-choice"><span class="mode-title"><input type="radio" name="mode" value="batch" ${prefill.mode==='batch'?'checked':''}> Research later</span><p>Queue your research.<br>Receive results by stage.</p><span class="saving">50% lower model token prices</span></label></div><p class="field-help" id="mode-help">Both modes use the same evidence checks. Search fees are unchanged.</p><div class="budget-row"><label for="budget">Project budget</label><div class="budget-input"><span>$</span><input id="budget" name="budget" type="number" min="1" max="100" step="0.5" required value="${esc(prefill.budget||state.bootstrap?.settings.defaultBudget||5)}"></div><span class="field-help">You control the spending allowance.</span></div><div class="inline-error" role="alert" id="project-error"></div></div><div class="form-bottom"><p>Every report includes sources<br>and questions still to resolve.</p><button class="button primary" type="submit" id="start-research">Start research <span aria-hidden="true">↗</span></button></div></form>
  <aside><div class="panel coverage"><div class="coverage-title">YOUR RESEARCH BRIEF</div>${[['pin','The right authorities','Building, planning, fire, and other agencies with authority over your address.'],['people','People you can contact','Publicly listed contacts, their responsibilities, and how to reach them.'],['book','The editions that apply','Adopted codes, referenced standards, effective dates, and local amendments.'],['check','Evidence you can inspect','Original sources, supporting passages, and clear gaps to confirm with the AHJ.']].map(([icon,title,text])=>`<div class="coverage-item"><span class="coverage-icon">${icons[icon]}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}</div><div class="evidence-note"><h3>Published doesn’t always mean adopted.</h3><p>The research traces local adoption documents and referenced editions. Unconfirmed requirements stay visible as questions to resolve.</p></div><p class="settings-hint">${state.bootstrap?.keyConfigured?'Your Claude connection is ready.':'Bring your own Claude API key. <button type="button" id="connect-hint">Connect your account</button> to begin.'}</p></aside></div>`;
  $('#project-form').addEventListener('submit',startProject);
  $('#discipline').addEventListener('change',()=>{const custom=$('#discipline').value==='Other';$('#custom-discipline-field').hidden=!custom;$('#custom-discipline').disabled=!custom;$('#custom-discipline').required=custom;if(custom)$('#custom-discipline').focus();});
  $('#connect-hint')?.addEventListener('click',openSettings);
  for(const radio of document.querySelectorAll('[name=mode]'))radio.addEventListener('change',()=>{$('#mode-help').textContent=radio.value==='batch'?'Batch stages can each take up to 24 hours; a multi-stage report can take longer. Search fees are unchanged.':'Both modes use the same evidence checks. Search fees are unchanged.';});
}
function renderSidebar(){
  $('#project-count').textContent=state.projects.length;
  $('#project-list').innerHTML=state.projects.length?state.projects.map(p=>`<button class="project-nav ${state.selected===p.id?'active':''}" data-project="${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${esc(p.discipline)} · ${esc(statuses[p.status]||p.status)}</small></button>`).join(''):'<p class="sidebar-empty">Your projects will appear here.</p>';
  for(const b of document.querySelectorAll('[data-project]'))b.addEventListener('click',()=>selectProject(b.dataset.project));
  $('#connection-label').textContent=state.bootstrap?.keyConfigured?'Claude connected':'Connect Claude';$('.connection-light').classList.toggle('on',Boolean(state.bootstrap?.keyConfigured));
}
async function startProject(e){e.preventDefault();if(!state.bootstrap.keyConfigured){openSettings();return;}const button=$('#start-research');button.disabled=true;button.textContent='Creating project…';try{const body=Object.fromEntries(new FormData(e.target));body.budget=Number(body.budget);if(body.discipline==='Other'){body.discipline=body.customDiscipline.trim();}delete body.customDiscipline;const p=await api('/api/projects',{method:'POST',body});await refreshProjects();await selectProject(p.id);}catch(error){$('#project-error').textContent=error.message;}finally{button.disabled=false;button.innerHTML='Start research <span aria-hidden="true">↗</span>';}}
async function refreshProjects(){state.projects=await api('/api/projects');renderSidebar();}
async function selectProject(id){const load=++projectLoad;state.selected=id;state.detail=null;state.tab=state.tab==='chat'?'chat':'overview';history.replaceState(null,'',`/#project=${encodeURIComponent(id)}`);renderSidebar();$('#main').innerHTML='<div class="loading">Opening project…</div>';try{const detail=await api(`/api/projects/${id}`);if(load!==projectLoad||state.selected!==id)return;state.detail=detail;renderProject();}catch(e){if(load===projectLoad)$('#main').innerHTML=`<div class="error-panel">${esc(e.message)}</div>`;}}
function statusClass(status){return ['complete','verified'].includes(status)?'green':['partial','budget','attention','conflicting','inferred','unverified','needs_key'].includes(status)?'amber':['failed','canceled'].includes(status)?'red':'';}
function badge(status){return `<span class="status-pill ${statusClass(status)}">${esc(({verified:'Source-supported',inferred:'Conditional',conflicting:'Conflicting',unverified:'Unconfirmed'})[status]||statuses[status]||status)}</span>`;}
function href(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function link(url,label){const safe=href(url);return safe?`<a href="${esc(safe)}" target="_blank" rel="noopener noreferrer">${esc(label||url)} ↗</a>`:'';}
function evidenceList(item){return item.evidence?.length?`<ul class="evidence-list">${item.evidence.map(e=>`<li><button class="banner-link" data-source="${esc(e.sourceId)}">${esc(e.sourceId)}${e.pageOrSection?' · '+esc(e.pageOrSection):''}</button>${e.supported?'':' · Supporting passage needs confirmation'}${e.quote?`<q>${esc(e.quote)}</q>`:''}</li>`).join('')}</ul>`:'';}
function empty(title,description){return `<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function questionForm(g){
  const key=state.selected+':'+g.id,busy=questionBusy.has(key),answer=questionDrafts.get(key)??g.answer??'';
  return `<form data-question-form="${esc(g.id)}"><label for="answer-${g.id}">Your answer</label><textarea id="answer-${g.id}" name="answer" rows="3" maxlength="4000" required placeholder="Share what you know about this project…" ${busy?'disabled':''}>${esc(answer)}</textarea><div class="question-actions"><button class="button primary" type="submit" ${busy?'disabled':''}>${busy?'Saving…':'Save answer'}</button>${g.status==='open'?`<button class="button secondary" type="button" data-question-action="dismissed" ${busy?'disabled':''}>Dismiss</button>`:''}</div></form>`;
}
function gapCards(gaps){return gaps.map(g=>`<article class="finding-card question-card" data-question="${esc(g.id)}"><div class="finding-top"><h3>${esc(g.question)}</h3>${g.status!=='open'?`<span class="status-pill ${g.status==='answered'?'green':''}">${g.status==='answered'?'Answered':'Dismissed'}</span>`:''}</div><p class="muted">${esc(g.why)}</p>${g.status==='open'?`<p>${esc(g.nextStep)}</p>${g.contact?`<p class="field-help">Contact: ${esc(g.contact)}</p>`:''}${questionForm(g)}`:`${g.status==='answered'?`<p class="question-answer">${esc(g.answer)}</p><p class="field-help">User-provided answer</p><details id="edit-${g.id}" class="question-edit"><summary>Edit answer</summary>${questionForm(g)}</details>`:'<p class="field-help">Set aside by you. You can reopen it at any time.</p>'}<button class="text-button" type="button" data-question-action="open" ${questionBusy.has(state.selected+':'+g.id)?'disabled':''}>Reopen question</button>`}<div class="inline-error" role="alert" data-question-error></div></article>`).join('');}
function questionsView(p){
  const questions=p.questions||[],open=questions.filter(g=>g.status==='open'),saved=questions.filter(g=>g.status!=='open');
  const canResearch=!['queued','researching','waiting_batch','waiting','canceling','needs_key'].includes(p.status)&&!state.detail.attempts.some(a=>['dispatching','pending','received','unknown'].includes(a.state));
  return `<section class="report-section" id="project-questions"><div class="finding-top"><h2>Questions to resolve</h2><span class="status-pill amber" aria-label="${open.length} open questions">${open.length}</span></div><p class="field-help question-help">Save what you know, or dismiss a question that is not a priority. Answers are saved to this project without starting research.</p>${p.questionResponses?.length?`<div class="question-research"><p class="field-help">${p.questionUpdatesPending?'Your updates are saved. Start a new research round to check their implications.':'Your saved answers and dismissals are included in the latest research context.'}</p>${canResearch?'<button class="button secondary" id="research-answers">Research with saved answers</button>':'<p class="field-help">You can start another round when the current research and outstanding requests have settled.</p>'}</div>`:''}${open.length?gapCards(open):empty(questions.length?'No open questions':'No additional questions identified',questions.length?'Your answered and dismissed questions are saved below.':'Review the source evidence with your project team before using it for design.')}${saved.length?`<details id="saved-questions" class="saved-questions"><summary>Answered & dismissed <span class="tab-count">${saved.length}</span></summary>${gapCards(saved)}</details>`:''}</section>`;
}
async function saveQuestion(card,status){
  const id=state.selected,questionId=card.dataset.question,key=id+':'+questionId;
  if(questionBusy.has(key))return;
  const answer=card.querySelector('textarea')?.value||'';
  questionBusy.add(key);card.querySelectorAll('button').forEach(b=>b.disabled=true);$('[data-question-error]',card).textContent='';
  try{
    await api(`/api/projects/${id}/questions`,{method:'POST',body:{questionId,status,answer}});
    questionDrafts.delete(key);questionBusy.delete(key);
    if(state.selected===id)await refreshSelected();
    toast(status==='answered'?'Answer saved.':status==='dismissed'?'Question dismissed. You can reopen it below.':'Question reopened.');
  }catch(e){
    const current=state.selected===id?document.querySelector(`[data-question="${questionId}"]`):null;
    if(current)$('[data-question-error]',current).textContent=e.message;
  }finally{questionBusy.delete(key);if(state.selected===id)document.querySelector(`[data-question="${questionId}"]`)?.querySelectorAll('button,textarea').forEach(b=>b.disabled=false);}
}
function overview(detail){
  const {project:p,stages,sources}=detail,r=p.report;
  if(!r)return `<div class="report-grid"><section><h2>Research in progress</h2>${stages.some(s=>s.output)?stages.filter(s=>s.output).map(s=>`<article class="finding-card"><div class="finding-top"><h3>${esc(stageLabels[s.id]||s.id)}</h3>${badge(s.status)}</div><p class="field-help">Working findings · final evidence review pending</p><details><summary>Read the working brief</summary><div class="prose">${esc(s.output)}</div></details>${s.note?`<p class="field-help">${esc(s.note)}</p>`:''}</article>`).join(''):empty('Building your evidence base','The research begins with your address and responsible authorities. Source-linked findings will appear here as each stage finishes.')}<div class="project-note">${p.mode==='batch'?'Each batch stage can take up to 24 hours; a report with dependent stages can take longer. Keep the local app running to advance stages automatically.':'Research requests are bounded by your spending allowance. If a source is unavailable, the report will explain what still needs confirmation.'}</div></section><aside class="panel panel-padding"><span class="eyebrow">PROJECT CONTEXT</span><h3>${esc(p.discipline)}</h3><p class="muted">${esc(p.input.scope||'Scope not specified')}<br>${esc(p.input.occupancy||'Building use not specified')}</p><p class="field-help">Expected permit date: ${esc(p.input.permitDate||'Not specified')}</p>${p.input.notes?`<p class="prose">${esc(p.input.notes)}</p>`:''}<div class="section-divider"></div><h3>Sources collected</h3><p class="muted">${sources.filter(s=>s.read_full).length} read as evidence · ${sources.filter(s=>!s.read_full).length} discovered or visually inspected</p><button class="text-button" data-tab="sources">Inspect the source register →</button></aside></div>`;
  return `<div class="report-grid"><div><section class="panel panel-padding report-section"><span class="eyebrow">PROJECT BRIEFING</span><p class="prose">${esc(r.summary)}</p>${r.researchHealth?.incompleteStages?.length?`<p class="project-note">Some research is unfinished: ${esc(r.researchHealth.incompleteStages.map(s=>stageLabels[s.stage]||s.stage).join(", "))}. See the saved working briefs and questions to resolve.</p>`:""}</section><section class="report-section"><div class="finding-card"><div class="finding-top"><h2>Jurisdiction</h2>${badge(r.jurisdiction.status)}</div><h3>${esc(r.jurisdiction.authority)}</h3><p class="prose">${esc(r.jurisdiction.description)}</p>${r.jurisdiction.notes?`<p class="muted">${esc(r.jurisdiction.notes)}</p>`:''}${evidenceList(r.jurisdiction)}</div></section><section class="report-section"><h2>Reviewing authorities</h2>${r.authorities.length?r.authorities.map(a=>`<article class="finding-card"><div class="finding-top"><h3>${esc(a.name)}</h3>${badge(a.status)}</div><p>${esc(a.responsibility)}</p><p class="muted">${esc([a.phone,a.email,a.address].filter(Boolean).join(' · '))}</p>${link(a.website,'Official website')}${evidenceList(a)}</article>`).join(''):empty('Authorities not confirmed','See questions to resolve before relying on jurisdiction findings.')}</section><section class="report-section"><h2>Permits & submission requirements</h2>${r.requirements.length?r.requirements.map(q=>`<article class="finding-card"><div class="finding-top"><h3>${esc(q.title)}</h3>${badge(q.status)}</div><p class="field-help">${esc(q.authority)}</p><p class="prose">${esc(q.details)}</p>${link(q.website,'Submission resource')}${evidenceList(q)}</article>`).join(''):empty('No submission requirements verified','Check directly with the responsible authority for the current submission process.')}</section></div><aside>${questionsView(p)}<section class="panel panel-padding"><span class="eyebrow">RESEARCH COVERAGE</span>${Object.entries(r.coverage||{}).map(([k,v])=>`<h3>${esc(({jurisdiction:'Jurisdiction',contacts:'Contacts',codes:'Codes & standards',process:'Submission process'})[k]||k)}</h3><p class="field-help">${esc(v)}</p>`).join('')}</section></aside></div><p class="project-note">${esc(r.disclaimer)}</p>`;
}
function contactsView(r){if(!r)return empty('Contacts are being researched','Verified professional contacts will be organized here after the evidence review. Working briefs are available in Overview.');if(!r.contacts.length)return empty('No individual contacts confirmed','Use the responsible offices listed in Overview. Unpublished names and email addresses are not guessed.');return `<div class="contact-grid">${r.contacts.map(c=>`<article class="finding-card"><div class="finding-top"><div><span class="eyebrow">${esc(c.organization)}</span><h2>${esc(c.name||'Department contact')}</h2><p class="muted">${esc(c.title)}</p></div>${badge(c.status)}</div><p>${esc(c.responsibility)}</p><div class="contact-links">${c.email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)?`<a href="mailto:${esc(encodeURIComponent(c.email))}">${esc(c.email)}</a>`:''}${c.phone?`<a href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">${esc(c.phone)}</a>`:''}${link(c.website,'Website')}</div>${c.address?`<p class="field-help">${esc(c.address)}</p>`:''}${c.notes?`<p class="field-help">${esc(c.notes)}</p>`:''}${evidenceList(c)}</article>`).join('')}</div>`;}
const applicabilityLabel=value=>({applicable:'Applies to this scope',conditional:'Depends on project scope',not_applicable:'Not applicable — see basis',unresolved:'Applicability unresolved'})[value]||value;
function codeCount(r){return (r?.codes?.length||0)+(r?.fireStandards?.length||0);}
function codesView(r){
  const fire=state.detail.fireProfile?.length>0;
  const inactive=!['queued','researching','waiting_batch','waiting','canceling','needs_key'].includes(state.detail.project.status);
  const canUpdate=fire&&inactive&&state.detail.stages.filter(s=>['jurisdiction','contacts'].includes(s.id)).every(s=>s.status==='complete')&&!state.detail.attempts.some(a=>['unknown','dispatching','pending','received'].includes(a.state));
  const intro=fire?`<section class="panel panel-padding report-section"><div class="finding-top"><h2>Fire protection · NFPA standards</h2>${canUpdate?'<button class="button secondary" id="refresh-nfpa">Research NFPA standards</button>':''}</div><p>Each standard is checked for its adopted edition, legal basis, amendments, and relevance to your project. A screening target is not automatically a requirement.</p>${!r?.fireProtection?'<p class="field-help">This report has not completed the individual NFPA checklist. Run the focused update to investigate the missing standards using your existing project budget.</p>':`<p class="field-help">${r.fireStandards.length} individual findings · ${r.fireProtection.unresolved} need confirmation.${r.fireProtection.scopeConditional!==undefined?` ${r.fireProtection.scopeConditional} depend on project scope; ${r.fireProtection.applicabilityUnresolved} have unresolved applicability; ${r.fireProtection.evidenceUnresolved} still need evidence confirmation. These counts can overlap.`:" Scope-dependent and unresolved entries remain visible."}</p>`}<details><summary>Standards screened for this project</summary><p class="field-help">${state.detail.fireProfile.map(t=>esc(t.standard+' — '+t.topic)).join('<br>')}</p></details></section>`:'';
  if(!r)return intro+empty('Tracing adopted editions','The final tables appear after evidence review. Working research is saved in Overview.');
  return intro+'<p class="field-help" style="margin-bottom:18px">“Source-supported” means supporting passages were matched to retrieved text. Confirm applicability and unresolved amendments with the responsible authority.</p>'+(r.fireStandards?.length?codeTable(r.fireStandards):'')+(r.codes.length?`<section class="report-section" style="margin-top:28px">${fire?'<h2>Governing codes & other standards</h2>':''}${codeTable(r.codes)}</section>`:'');
}
function codeTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Code / standard</th><th>Edition</th><th>Authority & adoption</th><th>Evidence status</th><th>Applicability & evidence</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td><strong>${esc(c.edition||'Unconfirmed')}</strong><small>${c.effectiveDate?'Effective '+esc(c.effectiveDate):'Effective date unconfirmed'}</small></td><td>${esc(c.authority)}<small>${esc(({direct:'Direct adoption',referenced:'Incorporated by reference',guidance:'Agency guidance',unconfirmed:'Adoption unconfirmed'})[c.adoptionType]||c.adoptionType)}</small><small>${esc(c.adoptionInstrument)}</small></td><td>${badge(c.status)}</td><td class="code-detail">${c.applicabilityStatus?`<strong>${esc(applicabilityLabel(c.applicabilityStatus))}</strong>`:''}<p>${esc(c.applicability)}</p><details><summary>View amendments & sources</summary><p><strong>Local amendments:</strong> ${esc(c.amendments||'Not confirmed')}</p>${c.notes?`<p>${esc(c.notes)}</p>`:''}${evidenceList(c)}</details></td></tr>`).join('')}</tbody></table></div>`;}
function sourcesView(sources){if(!sources.length)return empty('No sources yet','Official webpages, ordinances, maps, and documents will be recorded here as they are found.');return sources.map(s=>`<article class="source-card" id="source-${esc(s.id)}"><div class="finding-top"><span class="eyebrow">${esc(s.id)} · ${esc(s.kind.replace('-',' '))}</span><span class="status-pill ${s.read_full?'green':''}">${s.read_full?'Read as evidence':'Discovered / visual only'}</span></div><h3>${link(s.url,s.title)}</h3><p>${esc(s.url)}</p><p>Retrieved ${esc(date(s.retrieved))}${s.document_date?' · Source modified '+esc(s.document_date):''}</p>${s.text?`<details><summary>Inspect retrieved excerpt</summary><div class="source-excerpt">${esc(s.text)}</div></details>`:'<p>Search discovery only. No full-source passage has been retrieved.</p>'}</article>`).join('');}
function activityView(detail){
  const {project:p,attempts,events}=detail;
  const used=attempts.filter(a=>Number.isFinite(a.usage?.output_tokens));
  const tokens=used.reduce((n,a)=>({input:n.input+Number(a.usage.input_tokens||0)+Number(a.usage.cache_read_input_tokens||0)+Number(a.usage.cache_creation_input_tokens||0),cached:n.cached+Number(a.usage.cache_read_input_tokens||0),output:n.output+Number(a.usage.output_tokens||0)}),{input:0,cached:0,output:0});
  const count=n=>Number(n).toLocaleString();
  return `<div class="report-grid"><section><h2>Research activity</h2><ol class="activity">${events.map(e=>`<li><time>${esc(date(e.time))}</time><span>${esc(e.message)}</span></li>`).join('')}</ol></section><aside><div class="panel panel-padding"><span class="eyebrow">SPENDING RECORD</span><h2>${money(p.cost)} <span class="optional">estimated API cost</span></h2><p class="cost-detail">${money(p.reserved)} reserved for pending or uncertain requests.<br>${money(p.finalAllowance)} held for the final report.<br>${money(p.budget)} project allowance.<br>${p.searches} searches · ${p.reads} source reads.</p><p class="field-help">The provider’s invoice is authoritative. Native search has variable input costs; a running request may exceed its estimate.</p><div class="section-divider"></div><h3>Recorded usage</h3><p class="field-help">${used.length} responses with usage recorded<br>${count(tokens.input)} input tokens<br>${count(tokens.cached)} cached input tokens (${tokens.input?Math.round(tokens.cached/tokens.input*100):0}%)<br>${count(tokens.output)} output tokens, including thinking</p><p class="field-help">Output ceilings: 60,000 per research or evidence-check request; 100,000 for the final report. Only actual token use is billed.</p></div>${attempts.filter(a=>a.batch_id||a.state==='unknown'||a.state==='errored').map(a=>`<div class="source-card" style="margin-top:15px"><h3>${esc(stageLabels[a.stage_id]||a.stage_id)} · ${esc(a.state)}</h3><p>Request: ${esc(a.id)}</p>${a.request_id?`<p>Provider request: ${esc(a.request_id)}</p>`:''}${a.batch_id?`<p>Batch: ${esc(a.batch_id)}</p>`:''}<p>Estimated charge: ${money(a.actual/1e6)}</p>${a.state==='unknown'?`<button class="button secondary" data-resolve="${esc(a.id)}">Resolve uncertain charge</button>`:''}</div>`).join('')}</aside></div>`;
}
function renderProject(){
  if(!state.detail)return;const {project:p,stages,sources,attempts}=state.detail,r=p.report;
  const focused=document.activeElement,editing=focused?.matches('[data-question-form] textarea, #chat-form textarea, #chat-form input')?{id:focused.id,start:focused.selectionStart,end:focused.selectionEnd}:null;
  const chatHistory=$('#chat-history'),chatScroll=chatHistory?{top:chatHistory.scrollTop,bottom:chatHistory.scrollHeight-chatHistory.scrollTop-chatHistory.clientHeight<40}:null;
  const openDetails=[...document.querySelectorAll('#main details[open]')].map(d=>d.closest('[id]')?.id).filter(Boolean);
  const active=['queued','researching','waiting_batch','waiting'].includes(p.status),uncertain=attempts.some(a=>a.state==='unknown');
  const canStop=!p.cancel_requested&&(active||p.finalAllowance>0||attempts.some(a=>a.stage_id!=='chat'&&['dispatching','pending','received'].includes(a.state)));
  $('#breadcrumb').innerHTML='WORKSPACE <span>/</span> PROJECT RESEARCH';
  $('#main').innerHTML=`<div class="intro"><div><span class="eyebrow">PROJECT RESEARCH</span><h1>${esc(p.name)}</h1><p>${esc(p.address)}</p><div class="report-meta"><span>${esc(p.discipline)}</span><span>·</span><span>${p.mode==='batch'?'Batch processing':'Real-time research'}</span>${badge(p.status)}</div></div><div class="project-actions"><button class="button secondary danger" id="delete-project">Delete project</button>${canStop?'<button class="button secondary danger" id="cancel-research">Stop research</button>':''}${!active&&!state.detail.chat?.active&&!['canceling','needs_key'].includes(p.status)&&!uncertain?'<button class="button secondary" id="resume-research">'+(researchComplete()?'Review or extend report':'Continue research')+'</button>':''}${p.status==='needs_key'?'<button class="button primary" id="project-connect">Connect Claude</button>':''}<details class="export-menu"><summary class="button secondary">Export <span aria-hidden="true">⌄</span></summary><div class="export-options">${[['pdf','PDF report'],['xlsx','Excel workbook'],['json','Research data (JSON)']].map(([f,label])=>`<a href="/api/projects/${p.id}/export?format=${f}" download>${label}</a>`).join('')}</div></details></div></div>
  <div class="summary-strip"><div class="summary-stat"><small>AUTHORITIES</small><strong>${r?r.authorities.length:'—'}</strong><em>${r?'identified':'researching'}</em></div><div class="summary-stat"><small>CODE & STANDARD FINDINGS</small><strong>${r?codeCount(r):'—'}</strong><em>${r?'entries':'researching'}</em></div><div class="summary-stat"><small>EVIDENCE SOURCES</small><strong>${sources.length}</strong><em>${sources.filter(s=>s.read_full).length} read</em></div><div class="summary-stat"><small>ESTIMATED COST / BUDGET</small><strong style="font-size:1.15rem">${money(p.cost)}</strong><em>/ ${money(p.budget)}</em><div class="cost-track"><span style="width:${Math.min(100,((p.cost+p.reserved+(p.finalAllowance||0))/p.budget)*100)}%"></span></div><small style="margin:7px 0 0">${money(p.reserved)} pending · ${money(p.finalAllowance)} held for final report</small></div></div>
  <div class="stages">${stages.map((s,i)=>`<div class="stage ${s.status==='complete'?'done':['running','preparing','waiting_batch'].includes(s.status)?'current':''}"><small>${s.status==='complete'?'✓':'0'+(i+1)} &nbsp; STAGE ${i+1}</small><strong>${esc(stageLabels[s.id]||s.id)}</strong><p>${esc(({queued:'Waiting',running:'Researching…',preparing:'Checking budget…',waiting_batch:'Awaiting batch result',complete:'Brief complete',partial:'Partial findings',blocked:'Needs attention'})[s.status]||s.status)}</p></div>`).join('')}</div>
  ${p.note?`<div class="notice ${['queued','researching','waiting_batch'].includes(p.status)?'info':''}"><p>${esc(p.note)}</p>${p.status==='budget'&&!attempts.some(a=>['dispatching','pending','received','unknown'].includes(a.state))?'<button class="button secondary" id="finish-partial">Finish with saved evidence</button>':''}${uncertain&&attempts.some(a=>a.mode==='batch'&&a.state==='unknown')?'<button class="button secondary" id="recover-batch">Reconcile original batch</button>':''}${uncertain?'<p class="field-help">Open Activity to inspect request identifiers and manually reconcile a confirmed charge.</p>':''}</div>`:''}
  <div class="tabs" role="tablist" aria-label="Project report">${[['overview','Overview',p.questions?.filter(q=>q.status==='open').length],['contacts','Contacts',r?.contacts.length],['codes','Codes & standards',codeCount(r)],['sources','Sources',sources.length],['chat','Chat with AI',null],['activity','Activity',null]].map(([id,label,count])=>`<button class="tab ${state.tab===id?'active':''}" role="tab" aria-selected="${state.tab===id}" aria-controls="report-content" data-tab="${id}">${label}${count?`<span class="tab-count">${count}</span>`:''}</button>`).join('')}</div><div id="report-content" role="tabpanel">${state.tab==='chat'?chatView(state.detail):state.tab==='contacts'?contactsView(r):state.tab==='codes'?codesView(r):state.tab==='sources'?sourcesView(sources):state.tab==='activity'?activityView(state.detail):overview(state.detail)}</div>`;
  for(const b of document.querySelectorAll('[data-tab]'))b.addEventListener('click',()=>{state.tab=b.dataset.tab;renderProject();});
  for(const b of document.querySelectorAll('[data-source]'))b.addEventListener('click',()=>{const id=b.dataset.source;state.tab='sources';renderProject();document.getElementById('source-'+id)?.scrollIntoView({behavior:'smooth',block:'center'});});
  $('#delete-project').addEventListener('click',()=>openAction('delete'));
  for(const b of document.querySelectorAll('[data-resolve]'))b.addEventListener('click',()=>openAction('resolve',b.dataset.resolve));
  for(const id of openDetails){const parent=document.getElementById(id);const d=parent?.matches('details')?parent:parent?.querySelector('details');if(d)d.open=true;}
  for(const form of document.querySelectorAll('[data-question-form]')){
    form.addEventListener('submit',e=>{e.preventDefault();saveQuestion(form.closest('[data-question]'),'answered');});
    $('textarea',form).addEventListener('input',e=>questionDrafts.set(state.selected+':'+form.dataset.questionForm,e.target.value));
  }
  for(const button of document.querySelectorAll('[data-question-action]'))button.addEventListener('click',()=>saveQuestion(button.closest('[data-question]'),button.dataset.questionAction));
  $('#research-answers')?.addEventListener('click',()=>openAction('resume'));
  bindChat();
  revealActiveTab();
  if(editing){const field=document.getElementById(editing.id);field?.focus({preventScroll:true});if(typeof editing.start==='number')field?.setSelectionRange(editing.start,editing.end);}
  const history=$('#chat-history');if(history)history.scrollTop=!chatScroll||chatScroll.bottom?history.scrollHeight:chatScroll.top;
  $('#refresh-nfpa')?.addEventListener('click',()=>openAction('nfpa'));$('#cancel-research')?.addEventListener('click',()=>openAction('cancel'));$('#resume-research')?.addEventListener('click',()=>openAction('resume'));$('#finish-partial')?.addEventListener('click',()=>openAction('partial'));$('#recover-batch')?.addEventListener('click',()=>openAction('reconcile'));$('#project-connect')?.addEventListener('click',openSettings);
}
function chatText(text){
  return esc(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\[(S\d+)\]/g,(match,id)=>state.detail?.sources.some(s=>s.id===id)?`<button class="banner-link" data-source="${id}" aria-label="Open source ${id}">[${id}]</button>`:match);
}
function chatAnswer(turn){
  if(!turn.answerParts?.length)return chatText(turn.answer);
  return turn.answerParts.map((part,partIndex)=>chatText(part.text)+(part.citations||[]).filter(c=>/^S\d+$/.test(c.sourceId)&&state.detail?.sources.some(s=>s.id===c.sourceId)).map((c,citationIndex)=>`<details class="chat-citation" id="chat-citation-${esc(turn.id)}-${partIndex}-${citationIndex}"><summary aria-label="Read supporting passage from ${esc(c.sourceId)}">[${esc(c.sourceId)}] Supporting passage</summary><div class="chat-citation-body"><strong>${esc(c.title)}</strong><blockquote>${esc(c.quote)}</blockquote><button class="text-button" data-source="${esc(c.sourceId)}">Open source ${esc(c.sourceId)}</button></div></details>`).join('')).join('');
}
function revealActiveTab(){
  const tabs=$('.tabs'),active=$('.tab.active');if(!tabs||!active)return;
  const left=active.getBoundingClientRect().left-tabs.getBoundingClientRect().left+tabs.scrollLeft;
  if(left<tabs.scrollLeft)tabs.scrollLeft=left;
  else if(left+active.offsetWidth>tabs.scrollLeft+tabs.clientWidth)tabs.scrollLeft=left+active.offsetWidth-tabs.clientWidth;
}
window.addEventListener('resize',revealActiveTab);
function chatTurns(detail){
  const rows=new Map([...(chatOlder.get(detail.project.id)?.turns||[]),...(detail.chat?.turns||[])].map(t=>[t.id,t]));
  return [...rows.values()].sort((a,b)=>a.created.localeCompare(b.created));
}
function chatView(detail){
  const p=detail.project,c=detail.chat||{},turns=chatTurns(detail),busy=Boolean(c.active)||chatPending.has(p.id),options=chatOptions.get(p.id)||{};
  const earlier=chatOlder.get(p.id)?.hasEarlier??c.hasEarlier;
  return `<section class="chat-panel panel"><div class="chat-heading"><div><span class="eyebrow">PROJECT CONVERSATION</span><h2>Chat about ${esc(p.name)}</h2><p class="field-help">Sonnet 5 · High reasoning · This project’s context and conversation only</p></div><span class="status-pill green">Project context only</span></div><div class="chat-context"><p>Ask about your report, sources, research notes, or saved answers. The assistant can look through all saved project records and cite the evidence.</p><p class="field-help">Chat uses saved evidence. Start a research round for new public-source lookups.</p></div><div class="chat-history" id="chat-history" role="log" aria-label="Project chat" aria-live="polite">${earlier?'<button class="text-button chat-earlier" id="chat-earlier">Show earlier messages</button>':''}${turns.length?turns.map(t=>`<article class="chat-turn"><div class="chat-message chat-user"><div class="chat-message-label">YOU <time>${esc(date(t.created))}</time></div><div class="chat-prose">${esc(t.user)}</div></div><div class="chat-message chat-assistant"><div class="chat-message-label">SONNET 5 ${t.status==='running'?'<span class="status-pill">Working…</span>':''}</div>${t.answer?`<div class="chat-prose">${chatAnswer(t)}</div>`:''}${t.note?`<p class="chat-note ${['failed','attention'].includes(t.status)?'chat-error':''}">${esc(t.note)}</p>`:''}${t.status==='attention'?'<button class="text-button" data-chat-activity>Review Activity</button>':''}${t.status!=='running'?`<p class="field-help">${esc(({complete:'Reply complete',limited:'Limit reached',failed:'Reply failed',stopped:'Stopped',interrupted:'Interrupted',attention:'Needs attention'})[t.status]||t.status)} · ${money(t.cost)} estimated${t.reserved?' · '+money(t.reserved)+' reserved':''}</p>`:''}</div></article>`).join(''):empty('Your project, in conversation','Ask which findings need attention, compare the saved code editions, or get help interpreting a cited passage.')}</div><form id="chat-form" class="chat-composer" data-chat-project="${p.id}"><label for="chat-message">Message about ${esc(p.name)}</label><textarea id="chat-message" name="message" rows="3" maxlength="6000" required placeholder="What should I resolve before submitting this project?" ${busy?'disabled':''}>${esc(chatDrafts.get(p.id)||'')}</textarea><details id="chat-spending"><summary>Spending & limits</summary><div class="form-row"><div><label for="chat-allowance">Allowance for this reply ($)</label><input type="number" id="chat-allowance" min="0.25" max="5" step="0.25" required value="${esc(options.allowance??1)}" ${busy?'disabled':''}></div><div><label for="chat-project-budget">Total project allowance ($)</label><input type="number" id="chat-project-budget" min="${Math.max(1,p.cost+p.reserved+p.finalAllowance).toFixed(6)}" max="100" step="any" required value="${esc(options.projectBudget??p.budget)}" ${busy?'disabled':''}></div></div><p class="field-help">Chat and research share this project’s allowance and your daily limit. Replies use real-time pricing, including for batch projects. The allowance stops new requests; provider billing for an in-flight request may exceed its estimate.</p><p class="field-help">Per reply: up to 4 requests, 8 project lookups, 5 minutes, 60,000 input tokens per request and 8,000 output tokens per request including reasoning. Two tasks can run at once across the workspace.</p></details><div id="chat-error" class="inline-error" role="alert">${esc(chatErrors.get(p.id)||'')}</div><div class="chat-send-row"><p class="field-help">${money(p.cost)} spent · ${money(p.reserved)} pending · ${money(p.budget)} project allowance</p>${c.active?'<button type="button" class="button secondary" id="chat-stop">Stop reply</button>':`<button type="submit" class="button primary" ${busy?'disabled':''}>${busy?'Sending…':'Send message'}</button>`}</div></form></section>`;
}
function bindChat(){
  const form=$('#chat-form');if(!form)return;const id=form.dataset.chatProject;
  $('#chat-message').addEventListener('input',e=>chatDrafts.set(id,e.target.value));
  for(const [selector,key] of [['#chat-allowance','allowance'],['#chat-project-budget','projectBudget']])$(selector).addEventListener('input',e=>chatOptions.set(id,{...chatOptions.get(id),[key]:e.target.value}));
  form.addEventListener('submit',async e=>{
    e.preventDefault();if(chatPending.has(id)||state.detail?.chat?.active)return;
    if(!state.bootstrap.keyConfigured){openSettings();return;}
    const message=$('#chat-message',form).value,allowance=Number($('#chat-allowance',form).value),projectBudget=Number($('#chat-project-budget',form).value);
    let request=chatRequests.get(id);if(!request||request.message!==message)request={message,clientId:crypto.randomUUID()};chatRequests.set(id,request);
    chatPending.add(id);chatErrors.delete(id);renderProject();
    try{
      const chat=await api(`/api/projects/${id}/chat`,{method:'POST',body:{...request,allowance,projectBudget}});
      chatRequests.delete(id);if(chatDrafts.get(id)===message)chatDrafts.delete(id);
      if(state.selected===id&&state.detail?.project.id===id){state.detail.chat=chat;await refreshSelected();}
    }catch(error){chatErrors.set(id,error.message);}
    finally{chatPending.delete(id);if(state.selected===id&&state.detail?.project.id===id)renderProject();}
  });
  $('#chat-stop')?.addEventListener('click',async()=>{const turnId=state.detail.chat.active;try{const chat=await api(`/api/projects/${id}/chat/stop`,{method:'POST',body:{turnId}});if(state.selected===id&&state.detail?.project.id===id){state.detail.chat=chat;renderProject();}}catch(e){chatErrors.set(id,e.message);if(state.selected===id)renderProject();}});
  $('#chat-earlier')?.addEventListener('click',async e=>{e.target.disabled=true;try{const before=chatTurns(state.detail)[0]?.id,chat=await api(`/api/projects/${id}/chat?before=${encodeURIComponent(before)}`),previous=chatOlder.get(id)?.turns||[];chatOlder.set(id,{turns:[...chat.turns,...previous],hasEarlier:chat.hasEarlier});if(state.selected===id&&state.detail?.project.id===id){renderProject();$('#chat-history').scrollTop=0;}}catch(e){chatErrors.set(id,e.message);if(state.selected===id)renderProject();}});
  for(const button of document.querySelectorAll('[data-chat-activity]'))button.addEventListener('click',()=>{state.tab='activity';renderProject();});
}
function researchComplete(){return Boolean(state.detail)&&state.detail.stages.filter(s=>s.id!=='review').every(s=>s.status==='complete');}
function openAction(type,attemptId){
  const p=state.detail.project;state.action={type,id:p.id,attemptId};$('#action-error').textContent='';
  $('#action-title').textContent=({delete:'Delete this project?',nfpa:'Research NFPA standards',resume:researchComplete()?'Review or extend report':'Continue project research',partial:'Finish a partial report',cancel:'Stop this research?',reconcile:'Reconcile the original batch',resolve:'Resolve an uncertain charge'})[type];
  $('#action-submit').textContent=({delete:'Delete project',nfpa:'Start focused NFPA research',resume:researchComplete()?'Start paid review / research':'Continue research',partial:'Prepare partial report',cancel:'Stop research',reconcile:'Check batch results',resolve:'Record confirmed charge'})[type];
  let html='';
  if(type==='delete')html=`<p>Permanently delete <strong>${esc(p.name)}</strong> and its saved report, sources, answers, and chat history?</p><p>This cannot be undone. Export anything you want to keep first.</p><p class="field-help">Recorded charges still count toward your daily spending allowance. Active requests must finish and uncertain charges must be resolved before deletion.</p>`;
  else if(type==='cancel')html='<p>No new requests will be started. Requests already running may finish and incur charges. Collected sources and results will be kept.</p>';
  else if(type==='reconcile')html='<p>Find the original batch in your Anthropic Console. Once it has finished, this app can match its exact request identifier and retrieve the result without resubmitting.</p><label for="batch-id">Original batch ID</label><input id="batch-id" name="batchId" required placeholder="msgbatch_…" autocomplete="off">';
  else if(type==='resolve')html=`<p>Check the original request in your Anthropic Console first. This releases the reservation and records the charge you confirm. It does not cancel a remote batch.</p><label for="actual-cost">Confirmed charge ($)</label><input id="actual-cost" name="actualCost" type="number" min="0" max="100" step="0.000001" required><label for="charge-note" style="margin-top:18px">How did you confirm the outcome?</label><textarea name="note" id="charge-note" rows="3" required maxlength="1000"></textarea><label class="check-label"><input type="checkbox" name="confirmed" required> I confirmed the original request finished, failed, or was canceled and checked its charge.</label>`;
  else html=`<p>${type==='nfpa'?'Research individual NFPA standards, check the evidence, and rebuild the report. Saved jurisdiction and contact research are retained. This uses Claude credits within the total allowance below.':type==='partial'?'Prepare a clearly labeled report using the evidence collected so far. This requires a final paid review.':p.questionUpdatesPending?'Your saved answers and dismissals will be included in a new research round. This uses Claude credits within the total allowance below.':researchComplete()?'Without new context or a follow-up question, this runs a paid review of the saved sources. Add context below to reopen research.':'Continue from saved work. Add context to recheck the findings, or change processing mode once outstanding requests have settled.'}</p><div class="form-row"><div><label for="resume-budget">Total project budget ($)</label><input id="resume-budget" name="budget" type="number" min="${Math.max(1,p.cost+p.reserved).toFixed(4)}" max="100" step="any" value="${p.budget}" required></div><div><label for="resume-mode">Processing mode</label><select id="resume-mode" name="mode"><option value="realtime" ${p.mode==='realtime'?'selected':''}>Research now</option><option value="batch" ${p.mode==='batch'?'selected':''}>Research later (batch)</option></select></div></div><p class="field-help">This is the total allowance, including ${money(p.cost)} already recorded.</p>${type==='resume'?'<label for="clarification" style="margin-top:20px">New project context <span class="optional">optional</span></label><textarea name="clarification" id="clarification" rows="3" maxlength="4000" placeholder="Permit date, confirmed AHJ, building use, or a specific question"></textarea><p class="field-help">Adding context reopens the research stages so existing findings can be checked against it.</p>':''}`;
  if(['resume','nfpa','partial'].includes(type)&&p.questionResponses?.length)html+='<p class="field-help">Saved answers and dismissals are included automatically. User-provided answers remain distinct from source evidence.</p>';
  $('#action-submit').classList.toggle('destructive',type==='delete');
  $('#action-content').innerHTML=html;$('#action-dialog').showModal();
  if(type==='delete')$('#action-dialog .dialog-actions [data-close]').focus();
}
$('#action-form').addEventListener('submit',async e=>{
  e.preventDefault();const a=state.action,values=Object.fromEntries(new FormData(e.target)),b=$('#action-submit');b.disabled=true;
  try{
    if(a.type==='delete'){
      await api(`/api/projects/${a.id}`,{method:'DELETE'});
      $('#action-dialog').close();
      for(const cache of [chatDrafts,chatOptions,chatPending,chatErrors,chatRequests,chatOlder])cache.delete(a.id);
      for(const key of questionDrafts.keys())if(key.startsWith(a.id+':'))questionDrafts.delete(key);
      state.projects=state.projects.filter(p=>p.id!==a.id);
      if(state.selected===a.id)newForm();else renderSidebar();
      await refreshProjects();toast('Project deleted.');return;
    }
    const endpoint=['partial','nfpa'].includes(a.type)?'resume':a.type==='resolve'?'resolve-charge':a.type;
    const body=a.type==='cancel'?{}:a.type==='resolve'?{attemptId:a.attemptId,actualCost:Number(values.actualCost),note:values.note,confirmed:values.confirmed==='on'}:a.type==='reconcile'?values:{budget:Number(values.budget),mode:values.mode,clarification:values.clarification||'',finishPartial:a.type==='partial',...(a.type==='nfpa'?{focus:'fire_protection'}:{})};
    await api(`/api/projects/${a.id}/${endpoint}`,{method:'POST',body});$('#action-dialog').close();await refreshSelected();toast(a.type==='cancel'?'Research is stopping. Saved work is retained.':'Project updated.');
  }catch(error){$('#action-error').textContent=error.message;}finally{b.disabled=false;}
});
async function refreshSelected(){
  const load=projectLoad;await refreshProjects();if(!state.selected||load!==projectLoad)return;
  const id=state.selected,next=await api(`/api/projects/${id}`);if(state.selected!==id||load!==projectLoad)return;
  const stamp=d=>JSON.stringify([d?.project.updated,d?.project.cost,d?.project.reserved,d?.events[0],d?.stages.map(s=>[s.status,s.rounds]),d?.chat]);
  const changed=stamp(next)!==stamp(state.detail);state.detail=next;if(changed)renderProject();
}
setInterval(()=>{if(!document.hidden&&state.bootstrap)refreshSelected().catch(()=>{});},5000);
function openSettings(){const b=state.bootstrap;$('#default-budget').value=b.settings.defaultBudget;$('#daily-budget').value=b.settings.dailyBudget;$('#remember-label').hidden=!b.windows;$('#remember-key').checked=Boolean(b.persisted);$('#api-key').value='';$('#api-key').placeholder=b.keyConfigured?'Connected · enter a key to replace it':'sk-ant-…';$('#key-note').textContent=b.persisted?'Your key is protected for this Windows account.':'Kept in memory for this session. Never included in reports.';$('#settings-error').textContent='';$('#settings-dialog').showModal();}
$('#new-project').addEventListener('click',()=>newForm());$('#open-settings').addEventListener('click',openSettings);$('#settings-top').addEventListener('click',openSettings);
for(const b of document.querySelectorAll('[data-close]'))b.addEventListener('click',()=>document.getElementById(b.dataset.close).close());
$('#settings-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('#save-settings');b.disabled=true;b.textContent='Checking connection…';try{await api('/api/settings',{method:'POST',body:{key:$('#api-key').value.trim(),remember:$('#remember-key').checked,defaultBudget:Number($('#default-budget').value),dailyBudget:Number($('#daily-budget').value)}});state.bootstrap=await api('/api/bootstrap');$('#api-key').value='';$('#settings-dialog').close();renderSidebar();toast('Workspace settings saved.');}catch(error){$('#settings-error').textContent=error.message;}finally{b.disabled=false;b.textContent='Save settings';}});
$('#forget-key').addEventListener('click',async()=>{try{await api('/api/connection',{method:'DELETE',body:{}});state.bootstrap=await api('/api/bootstrap');$('#api-key').value='';$('#remember-key').checked=false;renderSidebar();toast('API key disconnected and removed from saved storage.');}catch(e){$('#settings-error').textContent=e.message;}});
async function init(){try{state.bootstrap=await api('/api/bootstrap');await refreshProjects();const id=new URLSearchParams(location.hash.slice(1)).get('project');if(id&&state.projects.some(p=>p.id===id))await selectProject(id);else newForm();}catch(e){$('#main').innerHTML=`<div class="error-panel"><h2>Unable to open the workspace</h2><p>${esc(e.message)}</p><p>Keep the local application running, then reload this page.</p></div>`;}}
init().then(()=>{
  const ctx=document.modelContext;if(!ctx?.registerTool)return;
  const controller=new AbortController();
  for(const tool of [
    {name:'list_research_projects',title:'List AHJ research projects',description:'Read saved project names, disciplines, modes, and research status. Does not start research or spend funds.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{await refreshProjects();return state.projects.map(p=>({id:p.id,name:p.name,discipline:p.discipline,status:p.status,cost:p.cost}));}},
    {name:'open_research_project',title:'Open an AHJ research project',description:'Open an existing project in the visible workspace. Does not start or resume paid research.',inputSchema:{type:'object',properties:{projectId:{type:'string'}},required:['projectId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.projectId!=='string'||!state.projects.some(p=>p.id===input.projectId))throw new Error('Choose an existing project ID.');await selectProject(input.projectId);return {id:state.selected,status:state.detail.project.status};}},
  ])try{Promise.resolve(ctx.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>controller.abort(),{once:true});
});
